840	  // em restaurante.service.ts). Também força status pra 'pronto' se ainda tava 'preparando'
841	  // — garçom pode confirmar antes do Bar clicar o próprio "Entregue", e o item precisa sair
842	  // da fila ativa do Painel do Bar (senão fica preso lá achando que falta ação do Bar).
843	  // entregue_garcom é coluna própria, não mexe no status compartilhado com delivery.
844	  async confirmarEntregaItem(comandaId: number, garcomId: number, itemId: number) {
845	    await this.garantirComandaDoGarcom(comandaId, garcomId);
846	
847	    const { data: item } = await this.supabase.client
848	      .from('order_items')
849	      .select('id, status, pronto_em')
850	      .eq('id', itemId)
851	      .eq('order_id', comandaId)
852	      .maybeSingle();
853	    if (!item) throw new NotFoundException('Item não encontrado');
854	    if (item.status !== 'preparando' && item.status !== 'pronto') {
855	      throw new ForbiddenException('Item ainda não está em preparo');
856	    }
857	
858	    const agora = new Date().toISOString();
859	    const update: Record<string, unknown> = { entregue_garcom: true, entregue_em: agora };
860	    if (item.status === 'preparando') {
861	      update.status = 'pronto';
862	      update.pronto_em = item.pronto_em ?? agora;
863	    }
864	
865	    const { error } = await this.supabase.client.from('order_items').update(update).eq('id', itemId);
866	    if (error) throw error;
867	
868	    return this.obterComanda(comandaId, garcomId);
869	  }
870	
871	  // Corrige nome/telefone do cliente digitados errado na abertura — o garçom só corrige
872	  // enquanto a comanda ainda tá com ele (não faz sentido depois de paga/cancelada).
873	  async editarClienteMesa(comandaId: number, garcomId: number, body: { cliente_nome: string; cliente_telefone: string }) {
874	    const comanda = await this.garantirComandaDoGarcom(comandaId, garcomId);
875	    if (!['aberta', 'fechada_garcom'].includes(comanda.status)) {
876	      throw new BadRequestException('Só é possível editar comandas abertas ou aguardando pagamento');
877	    }
878	    if (!body.cliente_nome?.trim() || !body.cliente_telefone?.trim()) {
879	      throw new BadRequestException('Nome e telefone do cliente são obrigatórios');
880	    }
881	
882	    const { error } = await this.supabase.client
883	      .from('orders')
884	      .update({ cliente_mesa_nome: body.cliente_nome.trim(), cliente_mesa_telefone: body.cliente_telefone.trim() })

