261	const RestauranteCozinha = () => {
262	  const navigate = useNavigate();
263	
264	  // Detecta modo token sincronamente — antes da primeira renderização
265	  const [modoToken] = useState(() => {
266	    const params = new URLSearchParams(window.location.search);
267	    const urlToken = params.get('cozinha_token');
268	    if (urlToken) {
269	      setCozinhaToken(urlToken);
