300	  const tocarSom = useNotificacaoSonora('cozinha');
301	
302	  // Chrome pausa a fila do speechSynthesis sozinho depois de ~15s sem falar nada —
303	  // como a tela da cozinha fica ligada horas entre um pedido e outro, sem esse
304	  // keep-alive a voz para de sair silenciosamente (só o bipe continua, que é Web Audio).
305	  useEffect(() => {
306	    const synth = window.speechSynthesis;
307	    if (!synth) return;
