1	import { BadRequestException, ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
2	import * as crypto from 'crypto';
3	import { SupabaseService } from '../supabase/supabase.service';
4	import { SalaoService, ItemComandaBody } from './salao.service';
5	import { EstoqueService } from '../estoque/estoque.service';
6	import { CombosService, ItemExpandido } from '../combos/combos.service';
7	
8	const SESSAO_TTL_MS = 6 * 60 * 60 * 1000; // 6h — renovada a cada ação do cliente na mesa.
9	
10	// Cliente faz o pedido direto pela mesa via QR, sem depender do garçom (pedido do
11	// usuário 2026-08-03). Rota totalmente pública (sem login), no mesmo espírito do
12	// mesa-acompanhar.controller.ts — a única "credencial" é conhecer o token da mesa
13	// (impresso/exibido fisicamente) + a sessionId emitida na primeira entrada.
14	//
15	// Trava "1 cliente por mesa" (pedido explícito do usuário, item 7): a sessão fica
16	// presa à COMANDA (não à mesa em si) e só libera quando a comanda fecha — igual o
17	// ciclo de vida natural da mesa. Mesmo padrão de UPDATE condicional usado em
18	// garcons/motoboys (20260730000001_sessao_unica_garcom_motoboy.sql), só que aqui
19	// quem "expira" a sessão anterior é o fechamento da comanda, não um timer.
20	@Injectable()
21	export class AutoAtendimentoService {
22	  constructor(
23	    private supabase: SupabaseService,
24	    private estoque: EstoqueService,
25	    private combosService: CombosService,
26	    private salaoService: SalaoService,
27	  ) {}
28	
29	  private async resolverMesa(mesaToken: string) {
30	    const { data: mesa } = await this.supabase.client
31	      .from('mesas')
32	      .select('id, restaurant_id, status, numero, nome, restaurants(slug, name, auto_atendimento_habilitado, aparencia)')
33	      .eq('auto_atendimento_token', mesaToken)
34	      .maybeSingle();
35	    if (!mesa) throw new NotFoundException('Mesa não encontrada');
36	
37	    const restaurante = (mesa as any).restaurants;
38	    if (!restaurante?.auto_atendimento_habilitado) {
39	      throw new ForbiddenException('Auto atendimento não está disponível nesse estabelecimento.');
40	    }
41	    if (restaurante?.aparencia?.aberto !== true) {
42	      throw new ForbiddenException('Restaurante fechado no momento.');
43	    }
44	    return mesa as any;
45	  }
46	
47	  private async comandaAbertaDaMesa(mesaId: number) {
48	    const { data } = await this.supabase.client
49	      .from('orders')
50	      .select('id, status, restaurant_id, numero_comanda, cliente_session_id, cliente_session_expires_at, mesas(numero, nome)')
51	      .eq('mesa_id', mesaId)
52	      .eq('canal', 'presencial')
53	      .in('status', ['aberta', 'fechada_garcom'])
54	      .maybeSingle();
55	    return data as any;
56	  }
57	
58	  private sessaoValida(comanda: any, sessionId: string) {
59	    return (
60	      !!comanda.cliente_session_id &&
61	      comanda.cliente_session_id === sessionId &&
62	      !!comanda.cliente_session_expires_at &&
63	      new Date(comanda.cliente_session_expires_at).getTime() > Date.now()
64	    );
65	  }
66	
67	  private async garantirComandaDoCliente(mesaToken: string, sessionId: string) {
68	    if (!sessionId) throw new ForbiddenException('Sessão inválida — escaneie o QR da mesa novamente.');
69	    const mesa = await this.resolverMesa(mesaToken);
70	    const comanda = await this.comandaAbertaDaMesa(mesa.id);
71	    if (!comanda) throw new NotFoundException('Nenhum atendimento em andamento nessa mesa — escaneie o QR de novo.');
72	    if (!this.sessaoValida(comanda, sessionId)) {
73	      throw new ForbiddenException('Sessão encerrada — escaneie o QR da mesa de novo.');
74	    }
75	    comanda.restauranteSlug = mesa.restaurants?.slug ?? null;
76	    return comanda;
77	  }
78	
79	  // Primeiro scan da mesa: abre comanda nova (se estiver livre) e emite a sessão do
80	  // cliente. Se a mesa já tiver atendimento em andamento (garçom OU outro celular já
81	  // reivindicou a sessão), recusa — não deixa dois clientes disputarem a mesma mesa.
82	  async entrar(mesaToken: string) {
83	    const mesa = await this.resolverMesa(mesaToken);
84	    const existente = await this.comandaAbertaDaMesa(mesa.id);
85	    if (existente) {
86	      throw new ForbiddenException(
87	        existente.cliente_session_id
88	          ? 'Essa mesa já está em atendimento pelo celular de outro cliente.'
89	          : 'Essa mesa já está sendo atendida pelo garçom — chame a equipe.',
90	      );
91	    }
92	    if (mesa.status !== 'livre') throw new ForbiddenException('Mesa não está livre no momento.');
93	
94	    const { data: caixaAberto } = await this.supabase.client
95	      .from('caixas')
96	      .select('id')
97	      .eq('restaurant_id', mesa.restaurant_id)
98	      .eq('status', 'aberto')
99	      .maybeSingle();
100	
101	    const inicioDoDia = new Date();
102	    inicioDoDia.setHours(0, 0, 0, 0);
103	    const { count } = await this.supabase.client
104	      .from('orders')
105	      .select('id', { count: 'exact', head: true })
106	      .eq('restaurant_id', mesa.restaurant_id)
107	      .eq('canal', 'presencial')
108	      .gte('created_at', inicioDoDia.toISOString());
109	    const numeroComanda = (count ?? 0) + 1;
110	
111	    const sessionId = crypto.randomUUID();
112	    const expiresAt = new Date(Date.now() + SESSAO_TTL_MS).toISOString();
113	
114	    const { data: comanda, error } = await this.supabase.client
115	      .from('orders')
116	      .insert({
117	        restaurant_id: mesa.restaurant_id,
118	        canal: 'presencial',
119	        status: 'aberta',
120	        mesa_id: mesa.id,
121	        total: 0,
122	        caixa_id: caixaAberto?.id ?? null,
123	        numero_comanda: numeroComanda,
124	        aberto_por_nome: 'Auto Atendimento',
125	        cliente_session_id: sessionId,
126	        cliente_session_expires_at: expiresAt,
127	      })
128	      .select('id')
129	      .single();
130	    if (error) throw error;
131	
132	    await this.supabase.client.from('mesas').update({ status: 'ocupada' }).eq('id', mesa.id);
133	
134	    return {
135	      comandaId: comanda.id,
136	      sessionId,
137	      restauranteSlug: (mesa as any).restaurants?.slug ?? null,
138	      mesa: { numero: mesa.numero, nome: mesa.nome },
139	    };
140	  }
141	
142	  // Renova a validade da sessão a cada ação — cliente não some no meio do jantar
143	  // só porque passou o TTL inicial de 6h.
144	  private async renovarSessao(comandaId: number, sessionId: string) {
