12	const STATUS_ITEM_LABEL = { pendente: 'No carrinho', enviado: 'Enviado — aguardando preparo', preparando: 'Em preparo', pronto: 'Pronto!' };
13	
14	// Cliente escaneia o QR fixo da mesa e pede direto, sem depender do garçom (pedido do
15	// usuário 2026-08-03). Rota pública — a sessão vive no localStorage do celular
