20	  const [erro, setErro] = useState(null);
21	  const [sessao, setSessao] = useState(null);
22	  const [comanda, setComanda] = useState(null);
23	  const [cardapio, setCardapio] = useState(null);
24	  const [mostrarPicker, setMostrarPicker] = useState(false);
25	  const [categoriaAtiva, setCategoriaAtiva] = useState(null);
26	  const [adicionandoId, setAdicionandoId] = useState(null);
27	  const [solicitando, setSolicitando] = useState(false);
28	  const [msg, setMsg] = useState(null);
29	
30	  const carregarComanda = useCallback(async (sess) => {
31	    const data = await obterComandaAuto(token, sess.sessionId);
32	    setComanda(data);
33	    return data;
34	  }, [token]);
35	
36	  useEffect(() => {
37	    let ativo = true;
38	    (async () => {
39	      setCarregando(true);
40	      setErro(null);
41	      try {
42	        let sess = getSessaoLocal(token);
43	        let data;
44	        if (sess) {
45	          try {
46	            data = await obterComandaAuto(token, sess.sessionId);
47	          } catch (e) {
48	            limparSessaoLocal(token);
49	            sess = null;
50	            throw e;
51	          }
52	        } else {
53	          const res = await entrarNaMesa(token);
54	          sess = { comandaId: res.comandaId, sessionId: res.sessionId };
55	          setSessaoLocal(token, sess);
56	          data = await obterComandaAuto(token, sess.sessionId);
57	        }
58	        if (!ativo) return;
59	        setSessao(sess);
60	        setComanda(data);
61	        if (data.restauranteSlug) {
62	          const cat = await getCardapioPorSlug(data.restauranteSlug);
63	          if (ativo) {
64	            setCardapio(cat);
65	            setCategoriaAtiva(cat.cardapio?.[0]?.id ?? null);
66	          }
67	        }
68	      } catch (e) {
69	        if (ativo) setErro(e.message ?? 'Não foi possível acessar essa mesa.');
70	      } finally {
71	        if (ativo) setCarregando(false);
72	      }
73	    })();
74	    return () => { ativo = false; };
75	  }, [token]);
76	
77	  // Poll leve pra acompanhar status dos itens já enviados (mesmo intervalo do mesa-acompanhar).
78	  useEffect(() => {
79	    if (!sessao) return;
80	    const interval = setInterval(() => {
81	      carregarComanda(sessao).catch(() => {});
82	    }, 15000);
83	    return () => clearInterval(interval);
84	  }, [sessao, carregarComanda]);
85	
86	  const adicionarProduto = async (produto) => {
87	    if (!sessao) return;
88	    setAdicionandoId(produto.id);
89	    setMsg(null);
90	    try {
91	      await adicionarItensAuto(token, sessao.sessionId, [{ product_id: produto.id, quantity: 1 }]);
92	      await carregarComanda(sessao);
93	    } catch (e) {
94	      setMsg({ tipo: 'erro', texto: e.message ?? 'Não foi possível adicionar o produto.' });
95	    } finally {
96	      setAdicionandoId(null);
97	    }
98	  };
99	
100	  const handleSolicitarPedido = async () => {
101	    setSolicitando(true);
102	    setMsg(null);
103	    try {
104	      await solicitarPedidoAuto(token, sessao.sessionId);
105	      setMsg({ tipo: 'ok', texto: 'Pedido enviado pra cozinha!' });
106	    } catch (e) {
107	      setMsg({ tipo: 'erro', texto: e.message ?? 'Não foi possível enviar o pedido.' });
108	    } finally {
109	      setSolicitando(false);
110	    }
111	  };
112	
113	  if (carregando) {
114	    return <div className="min-h-screen flex items-center justify-center text-sm text-[#71717A]">Carregando...</div>;
115	  }
116	  if (erro) {
117	    return (
118	      <div className="min-h-screen flex items-center justify-center p-6 text-center">
119	        <p className="text-sm text-red-600">{erro}</p>
120	      </div>
121	    );
122	  }
123	  if (!comanda) return null;
