125	  const itensPendentes = comanda.itens.filter((i) => i.status === 'pendente');
126	  const itensEnviados = comanda.itens.filter((i) => i.status !== 'pendente');
127	  const totalPendente = itensPendentes.reduce((acc, i) => acc + i.quantity * i.unit_price, 0);
