139	            {comanda.mesa ? `Mesa ${comanda.mesa.numero}${comanda.mesa.nome ? ' - ' + comanda.mesa.nome : ''}` : ''}
140	            {comanda.numeroComanda ? ` — Comanda #${comanda.numeroComanda}` : ''}
141	          </p>
142	        </div>
143	
144	        {msg && (
145	          <div className={`rounded-xl px-3 py-2 mb-3 text-sm text-center ${msg.tipo === 'ok' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>
146	            {msg.texto}
147	          </div>
148	        )}
149	
150	        <button onClick={() => setMostrarPicker(true)}
151	          className="w-full mb-3 py-3 bg-[#FF441F] hover:bg-[#E63A19] text-white font-bold rounded-xl flex items-center justify-center gap-2">
152	          <Icon name="Plus" size={16} /> Inserir produto
153	        </button>
154	
155	        {itensPendentes.length > 0 && (
156	          <div className="bg-white rounded-2xl border border-[#E4E4E7] p-4 mb-3">
157	            <p className="text-xs font-bold text-[#71717A] uppercase mb-2">No carrinho (ainda não enviado)</p>
158	            <div className="space-y-2">
159	              {itensPendentes.map((item) => (
160	                <div key={item.id} className="flex items-center justify-between text-sm">
161	                  <span className="text-[#18181B]">{item.quantity}x {item.products?.name}</span>
162	                  <span className="text-[#71717A]">{fmt(item.quantity * item.unit_price)}</span>
