169	            </div>
170	          </div>
171	        )}
172	
173	        {itensEnviados.length > 0 && (
174	          <div className="bg-white rounded-2xl border border-[#E4E4E7] p-4 mb-3">
175	            <p className="text-xs font-bold text-[#71717A] uppercase mb-2">Já enviados</p>
