      const r = await tentarEntrar();
      if (!r.aguardando) {
        setAguardando(null);
        setSessao(r.sess);
        setComanda(r.data);
        await carregarCardapio(r.data.restauranteSlug);
      }
    } catch {}
  }, 8000);
  return () => clearInterval(interval);
}, [aguardando, sessao, tentarEntrar, carregarCardapio]);

