    subtotal: saldo.subtotal,
    desconto: comanda.desconto_valor ?? 0,
    acrescimo: comanda.acrescimo_valor ?? 0,
    gorjeta: gorjetaValor,
    gorjetaEstimativa,
    taxaCartaoTotal: parseFloat(taxaCartaoTotal.toFixed(2)),
