const naoEntregou = async (item) => {
  if (!window.confirm(`Confirma que NÃO entregou ${item.products?.name}? O item volta pra fila de preparo.`)) return;
  setErro(null);
  try {
    await naoEntregarItem(comandaId, item.id);
